mapper.select:
SELECT SYS_CD
     , SYS_CDNM
  FROM WMS.TB_COMM_CODE
 WHERE 1 = 1
   AND SYS_GRP_CD = #{ sys_grp_cd }   -- 그룹 코드

   AND SRVC_CD = #{ srvc_cd }


   AND SYS_ETC1 = #{ sys_etc1 }


   AND SYS_ETC2 = #{ sys_etc2 }


   AND SYS_ETC3 = #{ sys_etc3 }


   AND SYS_ETC4 = #{ sys_etc4 }


   AND SYS_ETC5 = #{ sys_etc5 }

   AND USE_YN     = 'Y'

 ORDER BY SYS_SORT_SEQ, SYS_CD

SELECT CLIENT_CD
     , CLIENT_NM
     , USE_YN
  FROM WMS.TB_CLIENT
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND CLIENT_CD LIKE '%' || #{clientCd} || '%'


   AND USE_YN = #{useYn}

 ORDER BY CLIENT_CD

SELECT VEHICLE_NO
     , DRV_NM
     , USE_YN
  FROM WMS.TB_VEHICLE
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND VEHICLE_NO LIKE '%' || #{vehicleNo} || '%'


   AND USE_YN = #{useYn}

 ORDER BY VEHICLE_NO

SELECT ZONE_CD
     , ZONE_NM
     , USE_YN
  FROM WMS.TB_ZONE
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND ZONE_CD LIKE '%' || #{zoneCd} || '%'


   AND USE_YN = #{useYn}

 ORDER BY ZONE_CD

SELECT LOC_CD
     , ZONE_CD
     , USE_YN
  FROM WMS.TB_LOC
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}

   AND ZONE_CD = #{zoneCd}


   AND LOC_CD LIKE '%' || #{locCd} || '%'


   AND USE_YN = #{useYn}

 ORDER BY ZONE_CD, LOC_CD

SELECT PROD_CD , PROD_NM FROM WMS.TB_ITEM WHERE 1 = 1 AND SRVC_CD = #{srvcCd} AND WH_CD = #{whCd}
AND PROD_CD LIKE '%' || #{prodCd} || '%'
AND USE_YN = 'Y' ORDER BY PROD_CD
